#!/usr/bin/env python3
"""Offline compiler from complete service-invocation-path policy bundles to a
canonical, minimal, total DFA with per-state viability distances.

Reads one JSON request per physical line from stdin and emits one JSON object
per line on stdout.  Errors are reported with the codes E_JSON, E_SCHEMA,
E_LIMIT and E_COMPLEXITY as specified by the contract.
"""

import json
import sys
from collections import deque

# --------------------------------------------------------------------------
# contract limits
# --------------------------------------------------------------------------

MAX_LINE_BYTES = 1048576
MAX_DEPTH = 64
MAX_PRODUCT = 20000
MAX_SERVICES = 24
MAX_SERVICE_LEN = 64
MAX_RULES = 32
MAX_NODES = 256
MAX_ARGS = 32
MAX_ATOM_PATH = 16
MAX_ATOMS = 10
MAX_QUERIES = 256
MAX_QUERY_LEN = 4096
MAX_QUERY_TOKENS = 16384

E_JSON = '{"ok":false,"error":"E_JSON"}'
E_LIMIT = '{"ok":false,"error":"E_LIMIT"}'
E_SCHEMA = '{"ok":false,"error":"E_SCHEMA"}'
E_COMPLEXITY = '{"ok":false,"error":"E_COMPLEXITY"}'

ATOM_OPS = frozenset(('match', 'startswith', 'endswith', 'contains'))


class CodedError(Exception):
    """Carries one of the four specified error codes."""

    __slots__ = ('code',)

    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


# --------------------------------------------------------------------------
# JSON front end
# --------------------------------------------------------------------------

def _reject_constant(_name):
    raise CodedError('E_JSON')


def _pairs_hook(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise CodedError('E_JSON')
        out[key] = value
    return out


def _json_load(text):
    return json.loads(text, parse_constant=_reject_constant,
                      object_pairs_hook=_pairs_hook)


def depth_ok(text):
    """Preliminary nesting scan (strings and escapes counted as JSON does)."""
    depth = 0
    in_string = False
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if in_string:
            if c == '\\':
                i += 2
                continue
            if c == '"':
                in_string = False
        else:
            if c == '"':
                in_string = True
            elif c == '{' or c == '[':
                depth += 1
                if depth > MAX_DEPTH:
                    return False
            elif c == '}' or c == ']':
                if depth:
                    depth -= 1
        i += 1
    return True


def check_scalars(value):
    """Every string in the document must hold valid Unicode scalar values."""
    stack = [value]
    while stack:
        item = stack.pop()
        kind = type(item)
        if kind is str:
            for ch in item:
                if 0xD800 <= ord(ch) <= 0xDFFF:
                    raise CodedError('E_SCHEMA')
        elif kind is list:
            stack.extend(item)
        elif kind is dict:
            for key, sub in item.items():
                for ch in key:
                    if 0xD800 <= ord(ch) <= 0xDFFF:
                        raise CodedError('E_SCHEMA')
                stack.append(sub)


# --------------------------------------------------------------------------
# schema validation (stage 4) -> normalized syntax trees
#   ('const', bool) | ('not', e) | ('and', [e..]) | ('or', [e..])
#   (op, (token, ...))            for the four atoms
# --------------------------------------------------------------------------

def validate_expr(node, services_set):
    if type(node) is not dict:
        raise CodedError('E_SCHEMA')
    op = node.get('op')
    if op == 'true':
        if len(node) != 1:
            raise CodedError('E_SCHEMA')
        return ('const', True)
    if op == 'false':
        if len(node) != 1:
            raise CodedError('E_SCHEMA')
        return ('const', False)
    if op == 'not':
        if len(node) != 2 or 'arg' not in node:
            raise CodedError('E_SCHEMA')
        return ('not', validate_expr(node['arg'], services_set))
    if op == 'and' or op == 'or':
        if len(node) != 2 or 'args' not in node:
            raise CodedError('E_SCHEMA')
        args = node['args']
        if type(args) is not list:
            raise CodedError('E_SCHEMA')
        return (op, [validate_expr(a, services_set) for a in args])
    if op in ATOM_OPS:
        if len(node) != 2 or 'path' not in node:
            raise CodedError('E_SCHEMA')
        path = node['path']
        if type(path) is not list:
            raise CodedError('E_SCHEMA')
        for tok in path:
            if type(tok) is not str or tok not in services_set:
                raise CodedError('E_SCHEMA')
        return (op, tuple(path))
    raise CodedError('E_SCHEMA')


def validate_bundle(doc):
    if type(doc) is not dict:
        raise CodedError('E_SCHEMA')
    if len(doc) != 3:
        raise CodedError('E_SCHEMA')
    if 'services' not in doc or 'rules' not in doc or 'queries' not in doc:
        raise CodedError('E_SCHEMA')

    services = doc['services']
    if type(services) is not list:
        raise CodedError('E_SCHEMA')
    services_set = set()
    for tok in services:
        if type(tok) is not str:
            raise CodedError('E_SCHEMA')
        if not tok:
            raise CodedError('E_SCHEMA')
        if tok in services_set:
            raise CodedError('E_SCHEMA')
        services_set.add(tok)

    rules = doc['rules']
    if type(rules) is not list:
        raise CodedError('E_SCHEMA')
    rule_asts = []
    for rule in rules:
        if type(rule) is not dict:
            raise CodedError('E_SCHEMA')
        if len(rule) != 2 or 'action' not in rule or 'when' not in rule:
            raise CodedError('E_SCHEMA')
        action = rule['action']
        if action == 'allow':
            is_allow = True
        elif action == 'drop':
            is_allow = False
        else:
            raise CodedError('E_SCHEMA')
        rule_asts.append((is_allow, validate_expr(rule['when'], services_set)))

    queries = doc['queries']
    if type(queries) is not list:
        raise CodedError('E_SCHEMA')
    for path in queries:
        if type(path) is not list:
            raise CodedError('E_SCHEMA')
        for tok in path:
            if type(tok) is not str or tok not in services_set:
                raise CodedError('E_SCHEMA')

    return services, rule_asts, queries


# --------------------------------------------------------------------------
# size limits (stage 5)
# --------------------------------------------------------------------------

def measure_rules(rule_asts):
    """Returns (atom order list, node count).  Raises E_LIMIT on violation."""
    atoms = {}
    nodes = 0
    longest = 0
    stack = []
    for _is_allow, ast in rule_asts:
        stack.append(ast)
        while stack:
            node = stack.pop()
            nodes += 1
            tag = node[0]
            if tag == 'and' or tag == 'or':
                args = node[1]
                if len(args) > MAX_ARGS:
                    raise CodedError('E_LIMIT')
                stack.extend(args)
            elif tag == 'not':
                stack.append(node[1])
            elif tag == 'const':
                pass
            else:
                path = node[1]
                if len(path) > longest:
                    longest = len(path)
                if path not in atoms:
                    atoms[path] = None
    if nodes > MAX_NODES:
        raise CodedError('E_LIMIT')
    if longest > MAX_ATOM_PATH:
        raise CodedError('E_LIMIT')
    if len(atoms) > MAX_ATOMS:
        raise CodedError('E_LIMIT')
    return list(atoms), nodes


def check_limits(services, rule_asts, queries):
    if len(services) > MAX_SERVICES:
        raise CodedError('E_LIMIT')
    for tok in services:
        if len(tok) > MAX_SERVICE_LEN:
            raise CodedError('E_LIMIT')
    if len(rule_asts) > MAX_RULES:
        raise CodedError('E_LIMIT')
    atoms, _nodes = measure_rules(rule_asts)
    if len(queries) > MAX_QUERIES:
        raise CodedError('E_LIMIT')
    total = 0
    for path in queries:
        if len(path) > MAX_QUERY_LEN:
            raise CodedError('E_LIMIT')
        total += len(path)
    if total > MAX_QUERY_TOKENS:
        raise CodedError('E_LIMIT')
    return atoms


# --------------------------------------------------------------------------
# Boolean simplification (exact; used only to pick the product components)
# --------------------------------------------------------------------------

def simplify(node):
    tag = node[0]
    if tag == 'const':
        return node
    if tag == 'not':
        inner = simplify(node[1])
        if inner[0] == 'const':
            return ('const', not inner[1])
        return ('not', inner)
    if tag == 'and':
        kept = []
        for arg in node[1]:
            red = simplify(arg)
            if red[0] == 'const':
                if not red[1]:
                    return ('const', False)
                continue
            kept.append(red)
        if not kept:
            return ('const', True)
        if len(kept) == 1:
            return kept[0]
        return ('and', kept)
    if tag == 'or':
        kept = []
        for arg in node[1]:
            red = simplify(arg)
            if red[0] == 'const':
                if red[1]:
                    return ('const', True)
                continue
            kept.append(red)
        if not kept:
            return ('const', False)
        if len(kept) == 1:
            return kept[0]
        return ('or', kept)
    return node


def collect_atoms(node, out):
    stack = [node]
    while stack:
        cur = stack.pop()
        tag = cur[0]
        if tag == 'and' or tag == 'or':
            stack.extend(cur[1])
        elif tag == 'not':
            stack.append(cur[1])
        elif tag == 'const':
            pass
        else:
            if cur not in out:
                out[cur] = None


# --------------------------------------------------------------------------
# atomic monitors (exactly as the contract defines them)
# --------------------------------------------------------------------------

def make_monitor(op, path, tokens):
    m = len(path)
    n = len(tokens)
    if op == 'match':
        size = m + 2
        dead = m + 1
        table = [[dead] * n for _ in range(size)]
        for k in range(m):
            want = path[k]
            row = table[k]
            for t in range(n):
                if tokens[t] == want:
                    row[t] = k + 1
        return table, m
    if op == 'startswith':
        size = m + 2
        dead = m + 1
        table = [[dead] * n for _ in range(size)]
        for k in range(m):
            want = path[k]
            row = table[k]
            for t in range(n):
                if tokens[t] == want:
                    row[t] = k + 1
        table[m] = [m] * n
        return table, m
    if op == 'endswith' or op == 'contains':
        size = m + 1
        table = []
        for k in range(size):
            if op == 'contains' and k == m:
                table.append([m] * n)
                continue
            base = path[:k]
            limit = k + 1
            if limit > m:
                limit = m
            row = []
            for t in range(n):
                seq = base + [tokens[t]]
                j = limit
                while j > 0:
                    if seq[k + 1 - j:] == path[:j]:
                        break
                    j -= 1
                row.append(j)
            table.append(row)
        return table, m
    raise AssertionError('unknown atom op')


def product_reachable_count(tables, alpha):
    """Distinct reachable monitor-product tuples; -1 once over the cap."""
    k = len(tables)
    if k == 0:
        return 1
    seen = {tuple([0] * k)}
    count = 1
    frontier = list(seen)
    tokens = range(alpha)
    while frontier:
        nxt_frontier = []
        for state in frontier:
            rows = [tables[j][state[j]] for j in range(k)]
            for t in tokens:
                nxt = tuple([row[t] for row in rows])
                if nxt not in seen:
                    seen.add(nxt)
                    count += 1
                    if count > MAX_PRODUCT:
                        return -1
                    nxt_frontier.append(nxt)
        frontier = nxt_frontier
    return count


# --------------------------------------------------------------------------
# product DFA for the referenced atoms
# --------------------------------------------------------------------------

def build_product(tables, truths, alpha, accept_of_mask):
    k = len(tables)
    start = tuple([0] * k)
    index = {start: 0}
    states = [start]
    accept = [accept_of_mask(0)]
    trans = []
    tokens = range(alpha)
    i = 0
    while i < len(states):
        state = states[i]
        rows = [tables[j][state[j]] for j in range(k)]
        row = []
        for t in tokens:
            nxt = tuple([r[t] for r in rows])
            j = index.get(nxt)
            if j is None:
                j = len(states)
                index[nxt] = j
                states.append(nxt)
                mask = 0
                bit = 1
                for c in range(k):
                    if nxt[c] == truths[c]:
                        mask |= bit
                    bit <<= 1
                accept.append(accept_of_mask(mask))
            row.append(j)
        trans.append(row)
        i += 1
    return trans, accept


# --------------------------------------------------------------------------
# minimization (Hopcroft) and canonical numbering
# --------------------------------------------------------------------------

def hopcroft_blocks(n, trans, accept, alpha):
    """Coarsest partition refinement; returns (blocks, block_of)."""
    acc_list = [s for s in range(n) if accept[s]]
    non_list = [s for s in range(n) if not accept[s]]
    blocks = []
    block_of = [0] * n
    if non_list:
        blocks.append(non_list)
    if acc_list:
        blocks.append(acc_list)
    for b, block in enumerate(blocks):
        for s in block:
            block_of[s] = b

    inv_off = []
    inv_flat = []
    for a in range(alpha):
        counts = [0] * n
        for s in range(n):
            counts[trans[s][a]] += 1
        off = [0] * (n + 1)
        running = 0
        for t in range(n):
            off[t] = running
            running += counts[t]
        off[n] = running
        flat = [0] * n
        pos = off[:n]
        for s in range(n):
            t = trans[s][a]
            flat[pos[t]] = s
            pos[t] += 1
        inv_off.append(off)
        inv_flat.append(flat)

    work = deque()
    in_work = bytearray(len(blocks))
    smallest = min(range(len(blocks)), key=lambda b: len(blocks[b]))
    work.append(smallest)
    in_work[smallest] = 1

    while work:
        b = work.popleft()
        in_work[b] = 0
        targets = blocks[b]
        for a in range(alpha):
            off = inv_off[a]
            flat = inv_flat[a]
            pred = set()
            for t in targets:
                lo = off[t]
                hi = off[t + 1]
                if hi > lo:
                    pred.update(flat[lo:hi])
            if not pred:
                continue
            groups = {}
            for s in pred:
                bid = block_of[s]
                got = groups.get(bid)
                if got is None:
                    groups[bid] = [s]
                else:
                    got.append(s)
            for cid, members in groups.items():
                block = blocks[cid]
                if len(members) == len(block):
                    continue
                mset = set(members)
                rest = [s for s in block if s not in mset]
                nid = len(blocks)
                blocks.append(members)
                blocks[cid] = rest
                for s in members:
                    block_of[s] = nid
                if in_work[cid]:
                    work.append(nid)
                    in_work[nid] = 1
                elif len(members) <= len(rest):
                    work.append(nid)
                    in_work[nid] = 1
                else:
                    work.append(cid)
                    in_work[cid] = 1
    return blocks, block_of


def canonical_dfa(trans, accept, alpha):
    """Minimize, then number states by BFS in declared alphabet order."""
    n = len(trans)
    blocks, block_of = hopcroft_blocks(n, trans, accept, alpha)
    qtrans = []
    qaccept = []
    for block in blocks:
        rep = block[0]
        row = trans[rep]
        qtrans.append([block_of[row[a]] for a in range(alpha)])
        qaccept.append(accept[rep])

    start_block = block_of[0]
    label = [-1] * len(blocks)
    label[start_block] = 0
    order = [start_block]
    queue = deque([start_block])
    while queue:
        b = queue.popleft()
        row = qtrans[b]
        for a in range(alpha):
            t = row[a]
            if label[t] < 0:
                label[t] = len(order)
                order.append(t)
                queue.append(t)

    nstates = len(order)
    accept_out = [qaccept[b] for b in order]
    next_out = []
    for b in order:
        row = qtrans[b]
        next_out.append([label[row[a]] for a in range(alpha)])
    return next_out, accept_out


def compute_distance(next_out, accept_out, alpha):
    n = len(next_out)
    dist = [None] * n
    queue = deque()
    for s in range(n):
        if accept_out[s]:
            dist[s] = 0
            queue.append(s)
    if queue:
        reverse = [[] for _ in range(n)]
        for s in range(n):
            row = next_out[s]
            for a in range(alpha):
                reverse[row[a]].append(s)
        while queue:
            u = queue.popleft()
            d = dist[u] + 1
            for v in reverse[u]:
                if dist[v] is None:
                    dist[v] = d
                    queue.append(v)
    return dist


# --------------------------------------------------------------------------
# top-level compilation of one request
# --------------------------------------------------------------------------

def compile_bundle(services, rule_asts, queries):
    alpha = len(services)

    allow_asts = []
    drop_asts = []
    for is_allow, ast in rule_asts:
        reduced = simplify(ast)
        (allow_asts if is_allow else drop_asts).append(reduced)

    referenced = {}
    for ast in allow_asts:
        collect_atoms(ast, referenced)
    for ast in drop_asts:
        collect_atoms(ast, referenced)
    ref_keys = list(referenced)

    all_monitors = {}
    for key in ref_keys:
        all_monitors[key] = make_monitor(key[0], key[1], services)
    tables = [all_monitors[key][0] for key in ref_keys]
    truths = [all_monitors[key][1] for key in ref_keys]

    allow_fns = [compile_expr(a, ref_keys) for a in allow_asts]
    drop_fns = [compile_expr(a, ref_keys) for a in drop_asts]
    cache = {}

    def accept_of_mask(mask):
        got = cache.get(mask)
        if got is None:
            got = any(f(mask) for f in allow_fns) and \
                not any(f(mask) for f in drop_fns)
            cache[mask] = got
        return got

    trans, accept = build_product(tables, truths, alpha, accept_of_mask)
    next_out, accept_out = canonical_dfa(trans, accept, alpha)
    distance = compute_distance(next_out, accept_out, alpha)

    token_index = {}
    for i, tok in enumerate(services):
        token_index[tok] = i
    rows = next_out
    results = []
    for path in queries:
        state = 0
        for tok in path:
            state = rows[state][token_index[tok]]
        results.append({'state': state, 'allow': accept_out[state],
                        'distance': distance[state]})

    return json.dumps({'ok': True,
                       'dfa': {'start': 0,
                               'accept': accept_out,
                               'next': next_out,
                               'distance': distance},
                       'queries': results}, separators=(',', ':'))


def compile_expr(node, atom_keys):
    tag = node[0]
    if tag == 'const':
        value = node[1]
        return lambda _mask: value
    if tag == 'not':
        inner = compile_expr(node[1], atom_keys)
        return lambda mask: not inner(mask)
    if tag == 'and':
        parts = [compile_expr(a, atom_keys) for a in node[1]]
        return lambda mask: all(f(mask) for f in parts)
    if tag == 'or':
        parts = [compile_expr(a, atom_keys) for a in node[1]]
        return lambda mask: any(f(mask) for f in parts)
    index = atom_keys.index(node)
    shift = 1 << index
    return lambda mask: (mask & shift) != 0


# --------------------------------------------------------------------------
# per-line driver
# --------------------------------------------------------------------------

def process(raw):
    try:
        if len(raw) > MAX_LINE_BYTES:
            return E_LIMIT
        try:
            text = raw.decode('utf-8')
        except UnicodeDecodeError:
            return E_JSON
        if not depth_ok(text):
            return E_LIMIT
        try:
            doc = _json_load(text)
        except CodedError:
            return E_JSON
        except (ValueError, RecursionError):
            return E_JSON

        check_scalars(doc)
        services, rule_asts, queries = validate_bundle(doc)
        all_atoms = check_limits(services, rule_asts, queries)

        tables = [make_monitor(op, path, services) for (op, path) in all_atoms]
        if product_reachable_count(tables, len(services)) < 0:
            return E_COMPLEXITY

        return compile_bundle(services, rule_asts, queries)
    except CodedError as err:
        code = err.code
        if code == 'E_JSON':
            return E_JSON
        if code == 'E_LIMIT':
            return E_LIMIT
        if code == 'E_SCHEMA':
            return E_SCHEMA
        return E_COMPLEXITY


def main():
    data = sys.stdin.buffer.read()
    lines = data.split(b'\n')
    if lines and not lines[-1]:
        lines.pop()
    out = []
    for raw in lines:
        out.append(process(raw))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')
    sys.stdout.flush()


if __name__ == '__main__':
    main()
